/* Real Chromium against production bundle; synthetic examples generated by real APIs. */
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
const root=path.resolve(__dirname,'../..'),output=process.argv[2],fixturePath=process.argv[3];
if(!output||fs.existsSync(output)||!fixturePath)throw Error('NEW output path and fixture required');
const fixture=JSON.parse(fs.readFileSync(fixturePath));const {chromium}=require(process.env.PLAYWRIGHT_MODULE_DIR+'/playwright');
const delay=ms=>new Promise(r=>setTimeout(r,ms));
(async()=>{const started=performance.now(),results=[],errors=[],external=[],calls=[];
 const browser=await chromium.launch({headless:true,executablePath:process.env.BROWSER_EXECUTABLE});const context=await browser.newContext({viewport:{width:1440,height:1050}});const page=await context.newPage();await page.addInitScript(()=>{window.requestTimes=[];const native=window.fetch;window.fetch=function(...args){window.requestTimes.push({url:String(args[0]),at:Date.now()});return native.apply(this,args);};});page.setDefaultTimeout(6500);page.on('pageerror',e=>errors.push(e.message));
 let control={};const measurements=[];const first=fixture.datasets[0],pdf=fixture.datasets[1],mainCandidate=first.responses['/candidates'].candidates[0];
 const safeJob=(ds,state)=>({...ds.job,state,events:state==='completed'?ds.job.events:[],attempt:state==='queued'?0:control.maxed?3:1,...(state==='failed'?{error_code:'workflow_internal_failure',error_category:control.permanent?'PERMANENT':'RETRYABLE'}:{error_code:null,error_category:null})});
 await page.route('**/*',async route=>{const req=route.request(),u=new URL(req.url());
  if(u.origin!=='http://127.0.0.1:4173'){external.push(u.origin);return route.abort();}
  const reply=(body,status=200)=>route.fulfill({status,contentType:'application/json',body:JSON.stringify(body)});
  if(u.pathname.startsWith('/api/')){calls.push({path:u.pathname,method:req.method(),headers:req.headers(),at:Date.now()});
   if(u.pathname==='/api/auth/status')return reply({provider_available:true,remote_enabled:false});
   if(u.pathname==='/api/auth/me')return control.anonymous?reply({},401):reply({user_id:'synthetic-reviewer',institution_id:'A',institution_name:'합성 연구지원기관',role:control.role||'manager',institution_admin:true,csrf_token:'synthetic-csrf'});
   if(u.pathname==='/api/documents'){control.listCalls=(control.listCalls||0)+1;if(control.listErrors){control.listErrors--;return reply({},503);}const docs=structuredClone(fixture.documents);if(control.foreignList)docs[0].institution_id='B';if(control.deregister)docs[0].registered=false;if(control.inactive)docs[0].active=false;return reply(docs);}
   const match=u.pathname.match(/^\/api\/documents\/([^/]+)\/versions\/([^/]+)(.*)$/);if(!match)return reply({},404);
   const ds=fixture.datasets.find(x=>x.document.document_id===match[1]&&x.document.id===match[2]);if(!ds){const doc=fixture.documents.find(d=>d.document_id===match[1]&&d.id===match[2]);return reply(doc||{},doc?200:404);}
   const tail=match[3];if(!tail){if(control.deregister)return reply({},404);return reply({...ds.document,active:control.inactive?false:true});}
   if(tail==='/original'){await delay(control.pdfDelay||0);return route.fulfill({status:200,contentType:'application/pdf',body:Buffer.from(ds.original_pdf_base64,'base64')});}
   if(tail.includes('/chunks/')){assert.equal(req.method(),'POST');assert.equal(req.headers()['x-csrf-token'],'synthetic-csrf');const ref=req.postDataJSON();let data=structuredClone(ds.resolved[ref.chunk_id]);if(control.badResolve)data.evidence.organization_id='B';return reply(data);}
   if(!tail.startsWith('/workflow'))return reply({},404);
   if(control.forbiddenAll)return reply({},403);
   const suffix=tail.slice('/workflow'.length);if(suffix==='/jobs'){assert.equal(req.method(),'POST');assert.equal(req.headers()['x-csrf-token'],'synthetic-csrf');assert.deepEqual(req.postDataJSON(),{});control.posts=(control.posts||0)+1;await delay(control.submitDelay||0);return reply(safeJob(ds,control.enqueueCompleted?'completed':control.enqueueCancelled?'cancelled':control.enqueueFailed?'failed':'queued'),202);}
   if(suffix.endsWith('/retry')){await delay(control.actionDelay||0);if(control.retryUnknown){control.retryUnknown=false;return reply({},503);}control.retries=(control.retries||0)+1;return reply(safeJob(ds,'queued'),202);}
   if(suffix.endsWith('/cancel')){await delay(control.actionDelay||0);control.cancels=(control.cancels||0)+1;return reply(safeJob(ds,'cancelled'));}
   if(suffix.startsWith('/jobs/')){control.polls=(control.polls||0)+1;if(control.statusDelay)await delay(control.statusDelay);if(control.statusErrors){control.statusErrors--;return reply({},control.statusCode||503);}if(control.statusHang){await delay(11000);}return reply(safeJob(ds,control.neverComplete?'processing':control.polls<2?'processing':'completed'));}
   if(suffix==='/candidates'&&control.workflowError){if(control.workflowError==='network')return route.abort();return reply({},control.workflowError);}
   if(control.late&&ds===first&&suffix==='/candidates')await delay(1200);
   let data=structuredClone(ds.responses[suffix+u.search]||ds.responses[suffix]);if(!data)return reply({},404);
   if(control.multipleEvidence&&suffix.startsWith('/candidates')&&!suffix.endsWith('/evidence'))data.candidates[0].steps[0].actions.push(structuredClone(data.candidates[0].steps[1].label));
   if(control.bigGraph&&suffix.startsWith('/candidates')&&!suffix.endsWith('/evidence')){const c=data.candidates[0];c.steps=[...c.steps,...Array.from({length:96},(_,i)=>({...structuredClone(c.steps[i%4]),id:'stress_'+i}))];}
   if(control.empty&&suffix==='/candidates')data.candidates=[];
   if(control.unsafe)data.semantic_verification='VERIFIED';
   if(control.mixedGeneration&&suffix.startsWith('/form-links'))data.generation_id='another-generation';
   if(control.foreignEvidence&&suffix.endsWith('/evidence'))data.evidence_refs[0].organization_id='B';
   if(control.unrenderable&&suffix.startsWith('/candidates')&&!suffix.endsWith('/evidence'))data.candidates[0].edges[0].target='unknown-step';
   try{return await reply(data);}catch{return;}
  }
  const dist=path.resolve(root,process.env.PHASE2E_DIST_DIR||'apps/web/dist'),file=path.resolve(dist,'.'+(u.pathname==='/'?'/index.html':u.pathname));if(u.pathname==='/favicon.ico')return route.fulfill({status:204,body:''});if(!file.startsWith(dist+path.sep)||!fs.existsSync(file))return route.abort();return route.fulfill({body:fs.readFileSync(file),contentType:file.endsWith('.js')?'text/javascript':file.endsWith('.css')?'text/css':'text/html'});
 });
 let bootId=0;
 async function boot(options={},ready=true){control={...options};await page.setViewportSize({width:1440,height:1050});await page.clock.install();await page.goto('http://127.0.0.1:4173/?case='+(++bootId)+'#/workflows');if(ready)await page.locator('.wf-original-quote').waitFor();}
 async function check(name,fn){try{await fn();results.push({name,status:'PASS'});console.log('PASS '+name);}catch(e){results.push({name,status:'FAIL',error:e.message});console.log('FAIL '+name+': '+e.message);}}
 async function step(index){await page.locator('.wf-map-node').nth(index).click();await page.locator('.wf-original-quote').filter({hasText:mainCandidate.steps[index].label.evidence[0].quote}).waitFor();}

 async function tick(ms){for(let i=0;i<ms;i+=500){await page.clock.runFor(Math.min(500,ms-i));await page.waitForTimeout(10);}}
 async function hidden(value){await page.evaluate(value=>{Object.defineProperty(document,'hidden',{configurable:true,get:()=>value});Object.defineProperty(document,'visibilityState',{configurable:true,get:()=>value?'hidden':'visible'});document.dispatchEvent(new Event('visibilitychange'));},value);await page.waitForTimeout(50);}
 async function enqueue(){await page.getByRole('button',{name:'추출 작업 요청',exact:true}).click();await page.locator('.wf-job').waitFor();}
 const baseline=process.env.PHASE2E_BASELINE==='1';
 try{
 await check('measured completed job idle requests over 20 virtual seconds',async()=>{await boot({enqueueCompleted:true});await enqueue();await page.locator('.wf-original-quote').waitFor();await page.waitForTimeout(80);const from=calls.length;await tick(20000);const sample=calls.slice(from);measurements.push({scenario:'completed_20s',requests:sample.length,paths:sample.map(c=>c.path)});if(!baseline)assert.equal(sample.length,0);});
 await check('100-node metadata refresh does not replace node data props',async()=>{await boot({bigGraph:true});assert.equal(await page.locator('.wf-map-node').count(),100);await page.evaluate(()=>{window.nodeData=()=>[...document.querySelectorAll('.wf-map-node')].map(n=>{let f=n[Object.keys(n).find(k=>k.startsWith('__reactFiber'))];while(f&&!f.memoizedProps?.data?.step)f=f.return;return f?.memoizedProps.data;});window.beforeData=window.nodeData();});const begin=performance.now();await tick(5500);const churn=await page.evaluate(()=>window.nodeData().filter((v,i)=>v!==window.beforeData[i]).length);measurements.push({scenario:'100_nodes_metadata_5_5s',node_data_replacements:churn,wall_ms:performance.now()-begin});if(!baseline)assert.equal(churn,0);await page.getByRole('button',{name:'단계 목록',exact:true}).click();assert.equal(await page.locator('.wf-step-list button').count(),100);});
 if(!baseline){
 await check('refresh requires explicit idempotent request; restores same queued job',async()=>{await boot({neverComplete:true});await enqueue();const firstId=fixture.datasets[0].job.id;await page.reload();await page.locator('.wf-original-quote').waitFor();assert.equal(control.posts,1);assert.equal(await page.locator('.wf-job').count(),0);await enqueue();assert.equal(control.posts,2);assert.ok(calls.some(c=>c.path.endsWith('/jobs')));await tick(2000);assert.ok(calls.some(c=>c.path.endsWith('/jobs/'+firstId)));assert.match(await page.locator('.wf-run').innerText(),/기존 작업이 없으면 새 작업/);});
 await check('failed terminal job stops timers and exposes only retryable retry',async()=>{await boot({enqueueFailed:true});await enqueue();await page.getByRole('button',{name:'실패 작업 재시도'}).waitFor();const from=calls.length;await tick(12000);assert.equal(calls.length,from);});
 await check('permanent failure cannot retry',async()=>{await boot({enqueueFailed:true,permanent:true});await enqueue();assert.equal(await page.getByRole('button',{name:'실패 작업 재시도'}).count(),0);assert.match(await page.locator('.wf-job').innerText(),/재시도할 수/);});
 await check('cancelled idempotent job is explicitly not resumable and stops timers',async()=>{await boot({enqueueCancelled:true});await enqueue();assert.match(await page.locator('.wf-job').innerText(),/재개할 수 없습니다/);const from=calls.length;await tick(12000);assert.equal(calls.length,from);});
 await check('hidden active job pauses all polling; visibility resumes',async()=>{await boot({neverComplete:true});await enqueue();await hidden(true);const from=calls.length;await tick(12000);assert.equal(calls.length,from);await hidden(false);await tick(500);assert.ok(calls.length>from);assert.ok(control.polls>=1);});
 await check('logout unmounts and stops polling',async()=>{await boot({neverComplete:true});await enqueue();control.anonymous=true;await page.evaluate(()=>window.dispatchEvent(new Event('seomuitda-session-expired')));await page.locator('#login-email').waitFor();await page.waitForTimeout(50);const from=calls.length;await tick(10000);assert.equal(calls.slice(from).filter(x=>x.path.includes('/documents')).length,0);});
 await check('503 retains job identity with unconfirmed state and backs off',async()=>{await boot({neverComplete:true,statusErrors:2});await enqueue();await tick(1800);assert.equal(control.polls,1);await page.getByText('현재 상태 미확인',{exact:true}).waitFor();await tick(2500);assert.equal(control.polls,1);await tick(1000);assert.equal(control.polls,2);await tick(5000);assert.equal(control.polls,2);await tick(2000);assert.ok(control.polls>=3);const times=await page.evaluate(()=>window.requestTimes.filter(x=>/\/jobs\/[^/]+$/.test(x.url)).map(x=>x.at));assert.ok(times[1]-times[0]>=3000);assert.ok(times[2]-times[1]>=6000);assert.match(await page.locator('.wf-job').innerText(),/분석 중/);});
 await check('status timeout remains recoverable and old response cannot confirm state',async()=>{await boot({neverComplete:true,statusHang:true});await enqueue();await tick(12000);await page.getByText('현재 상태 미확인',{exact:true}).waitFor();assert.match(await page.locator('.wf-job').innerText(),/시간이 초과/);control.statusHang=false;await tick(4000);assert.match(await page.locator('.wf-job').innerText(),/분석 중/);});
 await check('double retry submits once',async()=>{await boot({enqueueFailed:true,actionDelay:300});await enqueue();await page.getByRole('button',{name:'실패 작업 재시도'}).evaluate(n=>{n.click();n.click();});await page.waitForTimeout(450);assert.equal(control.retries,1);});
 await check('double cancel submits once',async()=>{await boot({neverComplete:true,actionDelay:300});await enqueue();await page.getByRole('button',{name:'작업 취소'}).evaluate(n=>{n.click();n.click();});await page.getByText('취소됨',{exact:true}).waitFor();assert.equal(control.cancels,1);});
 await check('multiple evidence selection survives step round trip',async()=>{await boot({multipleEvidence:true});const picker=page.locator('.wf-evidence-picker button');assert.equal(await picker.count(),2);await picker.nth(1).click();await page.locator('.wf-original-quote').waitFor();const quote=await page.locator('.wf-original-quote').innerText();await page.locator('.wf-map-node').nth(2).click();await page.locator('.wf-original-quote').waitFor();await page.locator('.wf-map-node').nth(0).click();await page.locator('.wf-original-quote').waitFor();assert.equal(await picker.nth(1).getAttribute('aria-pressed'),'true');assert.equal(await page.locator('.wf-original-quote').innerText(),quote);});
 await check('failed evidence stays unconfirmed and never shows original quote',async()=>{await boot({badResolve:true},false);await page.locator('[role=alert]').waitFor();assert.equal(await page.locator('.wf-original-quote').count(),0);assert.equal(await page.getByText('EvidenceRef 구조·출처 확인',{exact:true}).count(),0);assert.match(await page.locator('[role=alert]').innerText(),/검증 실패/);assert.ok(await page.getByText('근거 미확인',{exact:true}).count());});
 await check('source change while visible invalidates old candidate',async()=>{await boot();control.inactive=true;await tick(5500);assert.equal(await page.locator('.wf-original-quote').count(),0);});
 await check('reader never issues manager requests',async()=>{await boot({role:'reader'},false);await page.getByRole('heading',{name:'관리자 권한이 필요합니다'}).waitFor();const from=calls.length;await tick(6000);assert.equal(calls.slice(from).filter(x=>x.path.includes('/workflow')).length,0);});
 await check('429 status uses backoff and never confirms cached candidate',async()=>{await boot({neverComplete:true,statusErrors:1,statusCode:429});await enqueue();await tick(1800);await page.getByText('현재 상태 미확인',{exact:true}).waitFor();assert.equal(await page.locator('.wf-original-quote').count(),0);await tick(2200);assert.equal(control.polls,1);await tick(1500);assert.equal(control.polls,2);});
 await check('metadata errors use bounded backoff and recover',async()=>{await boot({listErrors:1},false);await page.locator('[role=alert]').waitFor();assert.equal(control.listCalls,1);await tick(9000);assert.equal(control.listCalls,1);await tick(2000);await page.locator('.wf-original-quote').waitFor();assert.equal(control.listCalls,2);});
 await check('retry limit is never reset by UI',async()=>{await boot({enqueueFailed:true,maxed:true});await enqueue();assert.equal(await page.getByRole('button',{name:'실패 작업 재시도'}).count(),0);assert.match(await page.locator('.wf-job').innerText(),/3\/3/);});
 await check('terminal focus checks current source and removes deregistered result',async()=>{await boot({enqueueCompleted:true});await enqueue();await page.locator('.wf-original-quote').waitFor();control.deregister=true;await page.evaluate(()=>window.dispatchEvent(new Event('focus')));await page.waitForTimeout(100);assert.equal(await page.locator('.wf-original-quote').count(),0);});
 await check('focus revalidation preserves step and selected evidence within same generation',async()=>{await boot({multipleEvidence:true,enqueueCompleted:true});await enqueue();await page.locator('.wf-original-quote').waitFor();await page.locator('.wf-evidence-picker button').nth(1).click();await page.locator('.wf-original-quote').waitFor();const quote=await page.locator('.wf-original-quote').innerText();await page.evaluate(()=>window.dispatchEvent(new Event('focus')));await page.waitForTimeout(100);await page.locator('.wf-original-quote').waitFor();assert.equal(await page.locator('.wf-evidence-picker button').nth(1).getAttribute('aria-pressed'),'true');assert.equal(await page.locator('.wf-original-quote').innerText(),quote);});
 await check('late status response cannot undo cancellation',async()=>{await boot({neverComplete:true,statusDelay:800});await enqueue();await tick(1800);assert.equal(control.polls,1);await page.getByRole('button',{name:'작업 취소'}).click();await page.getByText('취소됨',{exact:true}).waitFor();await page.waitForTimeout(1000);assert.match(await page.locator('.wf-job').innerText(),/취소됨/);const from=calls.length;await tick(5000);assert.equal(calls.length,from);});
 await check('lost retry acknowledgement rechecks server instead of trusting cached failure',async()=>{await boot({enqueueFailed:true,retryUnknown:true,neverComplete:true});await enqueue();await page.getByRole('button',{name:'실패 작업 재시도'}).click();await page.getByText('현재 상태 미확인',{exact:true}).waitFor();await tick(2000);assert.match(await page.locator('.wf-job').innerText(),/분석 중/);assert.ok(control.polls>=1);});
 await check('no sensitive or source storage or external traffic',async()=>{await boot();assert.equal(await page.evaluate(()=>localStorage.length+sessionStorage.length),0);assert.deepEqual(errors,[]);assert.deepEqual(external,[]);});
 }
 }finally{await browser.close();}
 const report={scope:baseline?'Phase2E-1 baseline measurement':'Phase2E-2A production Chromium with intercepted synthetic HTTP',measurements,results,counts:{PASS:results.filter(x=>x.status==='PASS').length,FAIL:results.filter(x=>x.status==='FAIL').length},seconds:(performance.now()-started)/1000,external,errors,clock:'Chromium virtual time, API routes settle between 500ms ticks; visibility API event simulation'};fs.writeFileSync(output,JSON.stringify(report,null,2));console.log(JSON.stringify(report.counts));if(report.counts.FAIL)process.exitCode=1;
})().catch(e=>{console.error(e);process.exitCode=1;});
